-- Seed fixture for PostgreSQL 15+ CI verification of src/supabase_rls_check/sql/check.sql.
-- Simulates Supabase roles + storage.buckets and plants one intentional misconfiguration
-- for each of the 8 catalog rules alongside hardened negative-control objects.

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN;
  END IF;
END
$$;

-- Mock Supabase Storage schema (rule: public_bucket + private control bucket)
CREATE SCHEMA IF NOT EXISTS storage;

CREATE TABLE storage.buckets (
  id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  public boolean NOT NULL DEFAULT false
);

INSERT INTO storage.buckets (id, name, public) VALUES
  ('documents', 'documents', true),
  ('private-backups', 'private-backups', false);

-- 1. public_extension: extension installed directly in public
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

-- 2. rls_disabled: public table without Row Level Security
CREATE TABLE public.todos (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);

-- 3. policy_true: RLS enabled, but policy USING expression is unconditionally true
CREATE TABLE public.profiles (
  id uuid PRIMARY KEY,
  display_name text NOT NULL
);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY allow_everyone ON public.profiles
  FOR SELECT TO authenticated
  USING (true);

-- 4. sensitive_anon_policy: anon role granted policy on sensitive table name
CREATE TABLE public.payments (
  id uuid PRIMARY KEY,
  amount numeric(10, 2) NOT NULL
);
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY anon_payments ON public.payments
  FOR SELECT TO anon
  USING (amount > 0);

-- 5. definer_search_path: SECURITY DEFINER trigger function with no fixed search_path
CREATE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN NEW;
END;
$$;

-- 6. definer_anon_exec: non-trigger SECURITY DEFINER RPC callable by anon (with search_path set)
CREATE FUNCTION public.create_order(uuid)
RETURNS uuid
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT $1;
$$;
GRANT EXECUTE ON FUNCTION public.create_order(uuid) TO anon;

-- 7. view_not_invoker: public view without security_invoker = true
CREATE VIEW public.customer_summary AS
  SELECT id, display_name FROM public.profiles;

-- Negative controls (properly configured objects that must NOT produce findings)
CREATE TABLE public.notes (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL,
  body text NOT NULL
);
ALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY notes_owner_only ON public.notes
  FOR ALL TO authenticated
  USING (owner_id IS NOT NULL)
  WITH CHECK (owner_id IS NOT NULL);

CREATE FUNCTION public.safe_admin_helper()
RETURNS integer
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT 1;
$$;
REVOKE ALL ON FUNCTION public.safe_admin_helper() FROM PUBLIC, anon;

CREATE VIEW public.safe_summary
  WITH (security_invoker = true) AS
  SELECT id, title FROM public.todos;

COMMIT;
